-- Migración 0036. Catálogo EXPEDICIONES_ESTATUS, historial y ID_ESTATUS
-- denormalizado en EXPEDICIONES. Transiciones automáticas por eventos;
-- FINALIZADO se marca por API. Unique de unidad abierta por ID_ESTATUS = 1.
-- No editar este archivo. El siguiente cambio va en una migración nueva
-- y debe reflejarse en db/init.sql.

BEGIN;

CREATE TABLE "EXPEDICIONES_ESTATUS" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CODIGO" text NOT NULL UNIQUE,
  "NOMBRE" text NOT NULL,
  "ACTIVO" boolean NOT NULL DEFAULT true,
  "ES_SEMILLA" boolean NOT NULL DEFAULT false,
  "CREADO_EN" timestamptz NOT NULL DEFAULT now(),
  "ACTUALIZADO_EN" timestamptz NOT NULL DEFAULT now()
);

CREATE TRIGGER "EXPEDICIONES_ESTATUS_ACTUALIZADO_TRG"
  BEFORE UPDATE ON "EXPEDICIONES_ESTATUS"
  FOR EACH ROW
  EXECUTE FUNCTION marcar_actualizado_en();

INSERT INTO "EXPEDICIONES_ESTATUS" ("ID", "CODIGO", "NOMBRE", "ES_SEMILLA") VALUES
  (1, 'ABIERTO', 'Abierto', true),
  (2, 'CERRADO', 'Cerrado', true),
  (3, 'TRANSITO', 'En tránsito', true),
  (4, 'RECEPCION', 'En recepción', true),
  (5, 'FINALIZADO', 'Finalizado', true);

SELECT setval(
  pg_get_serial_sequence('"EXPEDICIONES_ESTATUS"', 'ID'),
  (SELECT COALESCE(MAX("ID"), 1) FROM "EXPEDICIONES_ESTATUS")
);

CREATE TABLE "EXPEDICIONES_ESTATUS_HISTORIAL" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ID_EXPEDICION" integer NOT NULL,
  "ID_ESTATUS" integer NOT NULL,
  "FECHA" timestamptz NOT NULL DEFAULT now(),
  "ES_SEMILLA" boolean NOT NULL DEFAULT false,
  "CREADO_EN" timestamptz NOT NULL DEFAULT now(),
  "ACTUALIZADO_EN" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "EXPEDICIONES_ESTATUS_HISTORIAL_ID_EXPEDICION_FK"
    FOREIGN KEY ("ID_EXPEDICION") REFERENCES "EXPEDICIONES" ("ID"),
  CONSTRAINT "EXPEDICIONES_ESTATUS_HISTORIAL_ID_ESTATUS_FK"
    FOREIGN KEY ("ID_ESTATUS") REFERENCES "EXPEDICIONES_ESTATUS" ("ID")
);

CREATE INDEX "EXPEDICIONES_ESTATUS_HISTORIAL_ID_EXPEDICION_IDX"
  ON "EXPEDICIONES_ESTATUS_HISTORIAL" ("ID_EXPEDICION");

CREATE INDEX "EXPEDICIONES_ESTATUS_HISTORIAL_ID_ESTATUS_IDX"
  ON "EXPEDICIONES_ESTATUS_HISTORIAL" ("ID_ESTATUS");

CREATE INDEX "EXPEDICIONES_ESTATUS_HISTORIAL_FECHA_IDX"
  ON "EXPEDICIONES_ESTATUS_HISTORIAL" ("FECHA" DESC, "ID" DESC);

CREATE TRIGGER "EXPEDICIONES_ESTATUS_HISTORIAL_ACTUALIZADO_TRG"
  BEFORE UPDATE ON "EXPEDICIONES_ESTATUS_HISTORIAL"
  FOR EACH ROW
  EXECUTE FUNCTION marcar_actualizado_en();

CREATE OR REPLACE FUNCTION expedicion_sincronizar_estatus(
  p_id_expedicion integer
)
RETURNS void
LANGUAGE plpgsql
AS $$
DECLARE
  estatus_actual integer;
BEGIN
  SELECT h."ID_ESTATUS"
    INTO estatus_actual
  FROM "EXPEDICIONES_ESTATUS_HISTORIAL" AS h
  WHERE h."ID_EXPEDICION" = p_id_expedicion
  ORDER BY h."FECHA" DESC, h."ID" DESC
  LIMIT 1;

  UPDATE "EXPEDICIONES"
  SET "ID_ESTATUS" = estatus_actual
  WHERE "ID" = p_id_expedicion
    AND estatus_actual IS NOT NULL;
END;
$$;

CREATE OR REPLACE FUNCTION expedicion_registrar_estatus(
  p_id_expedicion integer,
  p_id_estatus integer
)
RETURNS void
LANGUAGE plpgsql
AS $$
BEGIN
  INSERT INTO "EXPEDICIONES_ESTATUS_HISTORIAL" (
    "ID_EXPEDICION",
    "ID_ESTATUS"
  )
  VALUES (
    p_id_expedicion,
    p_id_estatus
  );

  PERFORM expedicion_sincronizar_estatus(p_id_expedicion);
END;
$$;

ALTER TABLE "EXPEDICIONES"
  ADD COLUMN "ID_ESTATUS" integer;

UPDATE "EXPEDICIONES"
SET "ID_ESTATUS" = CASE
  WHEN "FECHA_CIERRE" IS NULL THEN 1
  ELSE 2
END;

INSERT INTO "EXPEDICIONES_ESTATUS_HISTORIAL" (
  "ID_EXPEDICION",
  "ID_ESTATUS",
  "FECHA"
)
SELECT
  e."ID",
  e."ID_ESTATUS",
  COALESCE(e."FECHA_CIERRE", e."CREADO_EN")
FROM "EXPEDICIONES" AS e;

ALTER TABLE "EXPEDICIONES"
  ALTER COLUMN "ID_ESTATUS" SET NOT NULL;

ALTER TABLE "EXPEDICIONES"
  ADD CONSTRAINT "EXPEDICIONES_ID_ESTATUS_FK"
    FOREIGN KEY ("ID_ESTATUS") REFERENCES "EXPEDICIONES_ESTATUS" ("ID");

CREATE INDEX "EXPEDICIONES_ID_ESTATUS_IDX"
  ON "EXPEDICIONES" ("ID_ESTATUS");

DROP INDEX "EXPEDICIONES_UNIDAD_ABIERTA_UQ";

CREATE UNIQUE INDEX "EXPEDICIONES_UNIDAD_ABIERTA_UQ"
  ON "EXPEDICIONES" ("ID_UNIDAD")
  WHERE "ID_ESTATUS" = 1;

CREATE OR REPLACE FUNCTION expediciones_estatus_despues_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  PERFORM expedicion_registrar_estatus(NEW."ID", 1);

  IF NEW."FECHA_CIERRE" IS NOT NULL THEN
    PERFORM expedicion_registrar_estatus(NEW."ID", 2);
  END IF;

  IF NEW."UBICACION_SALIDA_ID" IS NOT NULL
     AND (
       SELECT e."ID_ESTATUS" FROM "EXPEDICIONES" AS e WHERE e."ID" = NEW."ID"
     ) = 2 THEN
    PERFORM expedicion_registrar_estatus(NEW."ID", 3);
  END IF;

  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION expediciones_estatus_despues_update()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  estatus_actual integer;
BEGIN
  SELECT e."ID_ESTATUS" INTO estatus_actual
  FROM "EXPEDICIONES" AS e
  WHERE e."ID" = NEW."ID";

  IF OLD."FECHA_CIERRE" IS NULL
     AND NEW."FECHA_CIERRE" IS NOT NULL
     AND estatus_actual = 1 THEN
    PERFORM expedicion_registrar_estatus(NEW."ID", 2);
    estatus_actual := 2;
  END IF;

  IF OLD."UBICACION_SALIDA_ID" IS NULL
     AND NEW."UBICACION_SALIDA_ID" IS NOT NULL
     AND estatus_actual = 2 THEN
    PERFORM expedicion_registrar_estatus(NEW."ID", 3);
  END IF;

  RETURN NEW;
END;
$$;

CREATE TRIGGER "EXPEDICIONES_ESTATUS_INS_TRG"
  AFTER INSERT ON "EXPEDICIONES"
  FOR EACH ROW
  EXECUTE FUNCTION expediciones_estatus_despues_insert();

CREATE TRIGGER "EXPEDICIONES_ESTATUS_UPD_TRG"
  AFTER UPDATE ON "EXPEDICIONES"
  FOR EACH ROW
  EXECUTE FUNCTION expediciones_estatus_despues_update();

CREATE OR REPLACE FUNCTION recepciones_expedicion_estatus()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  estatus_actual integer;
BEGIN
  SELECT e."ID_ESTATUS" INTO estatus_actual
  FROM "EXPEDICIONES" AS e
  WHERE e."ID" = NEW."ID_EXPEDICION";

  IF estatus_actual = 3 THEN
    PERFORM expedicion_registrar_estatus(NEW."ID_EXPEDICION", 4);
  END IF;

  RETURN NEW;
END;
$$;

CREATE TRIGGER "RECEPCIONES_EXPEDICION_ESTATUS_TRG"
  AFTER INSERT ON "RECEPCIONES"
  FOR EACH ROW
  EXECUTE FUNCTION recepciones_expedicion_estatus();

CREATE OR REPLACE FUNCTION expediciones_lotes_validar()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  estatus_id integer;
  creada timestamptz;
  estatus_anterior integer;
  padre_id integer;
BEGIN
  IF TG_OP = 'DELETE' THEN
    SELECT "ID_ESTATUS" INTO estatus_id
    FROM "EXPEDICIONES"
    WHERE "ID" = OLD."ID_EXPEDICION";

    IF estatus_id IS DISTINCT FROM 1 THEN
      RAISE EXCEPTION 'la expedicion cerrada conserva sus lotes' USING ERRCODE = '23514';
    END IF;

    RETURN OLD;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    SELECT "ID_ESTATUS" INTO estatus_anterior
    FROM "EXPEDICIONES"
    WHERE "ID" = OLD."ID_EXPEDICION";

    IF estatus_anterior IS DISTINCT FROM 1 THEN
      RAISE EXCEPTION 'la expedicion cerrada conserva sus lotes' USING ERRCODE = '23514';
    END IF;
  END IF;

  SELECT "ID_ESTATUS", "CREADO_EN" INTO estatus_id, creada
  FROM "EXPEDICIONES"
  WHERE "ID" = NEW."ID_EXPEDICION";

  IF creada IS NULL THEN
    RAISE EXCEPTION 'expedicion inexistente' USING ERRCODE = '23503';
  END IF;

  IF estatus_id IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'no se embarcan lotes en una expedicion cerrada' USING ERRCODE = '23514';
  END IF;

  IF NEW."EMBARCADO_EN" < creada THEN
    RAISE EXCEPTION 'el embarque no puede ser anterior a la expedicion' USING ERRCODE = '23514';
  END IF;

  SELECT "PADRE_ID" INTO padre_id
  FROM "LOTES"
  WHERE "ID" = NEW."ID_LOTE";

  IF NOT FOUND THEN
    RAISE EXCEPTION 'lote inexistente' USING ERRCODE = '23503';
  END IF;

  IF padre_id IS NOT NULL THEN
    RAISE EXCEPTION 'solo se embarcan lotes sin padre' USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;

ALTER TABLE "EXPEDICIONES_ESTATUS" OWNER TO packing;
ALTER TABLE "EXPEDICIONES_ESTATUS_HISTORIAL" OWNER TO packing;
ALTER FUNCTION expedicion_sincronizar_estatus(integer) OWNER TO packing;
ALTER FUNCTION expedicion_registrar_estatus(integer, integer) OWNER TO packing;
ALTER FUNCTION expediciones_estatus_despues_insert() OWNER TO packing;
ALTER FUNCTION expediciones_estatus_despues_update() OWNER TO packing;
ALTER FUNCTION recepciones_expedicion_estatus() OWNER TO packing;

COMMIT;
